import csv, json, sys
from decimal import Decimal
from pathlib import Path
def total(rows):
    amounts = [Decimal(str(row["amount"])) for row in rows]
    if any(not amount.is_finite() for amount in amounts):
        raise ValueError("amount must be a finite numeric value")
    return sum(amounts, Decimal("0"))
def export(source, destination):
    rows = json.loads(Path(source).read_text(encoding="utf-8"))
    value = total(rows)
    target = Path(destination)
    target.mkdir(parents=True, exist_ok=True)
    with (target / "total.csv").open("w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["total"])
        writer.writerow([f"{value:.2f}"])
    (target / "total.html").write_text(f"<output>{value:.2f}</output>", encoding="utf-8")
if __name__ == "__main__":
    export(sys.argv[1], sys.argv[2])

